// event dose.missed (contract v1.1): {dose_id, patient_first_name, bed, meds[], scheduled_at, nurse_chat_ids[], doctor_chat_id, doctor_email}
const out = [];
for (const item of $input.all()) {
  const d = item.json.data || {};
  const at = d.scheduled_at ? DateTime.fromISO(d.scheduled_at).setZone('Africa/Tunis').toFormat('HH:mm') : '?';
  const text = `💊 Missed dose · Bed ${d.bed ?? '?'} · ${d.patient_first_name ?? 'Patient'} · ${(d.meds || []).join(', ') || 'meds'} (due ${at})`;
  const ids = [...(d.nurse_chat_ids || []), d.doctor_chat_id].filter(Boolean).map(String);
  for (const chat_id of [...new Set(ids)]) out.push({ json: { chat_id, text, dose_id: d.dose_id } });
}
return out;

const out = [];
for (const item of $input.all()) {
  const d = item.json.data || {};
  if (!d.doctor_email) continue;
  const at = d.scheduled_at ? DateTime.fromISO(d.scheduled_at).setZone('Africa/Tunis').toFormat('dd/LL HH:mm') : '?';
  out.push({ json: {
    to: d.doctor_email,
    subject: `Missed dose · Bed ${d.bed ?? '?'} · ${d.patient_first_name ?? 'Patient'}`,
    text: `The dose due at ${at} (${(d.meds || []).join(', ')}) was not taken within 30 minutes.\nBed ${d.bed ?? '?'} · ${d.patient_first_name ?? 'Patient'} · dose ${d.dose_id ?? ''}.\nThe ward nurses were notified on Telegram.\n\n— Ward`,
  } });
}
return out;
